<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { useDisplay } from 'vuetify'
import { salesOrdersApi } from '@/api/salesOrders'
import { salesDocumentsApi } from '@/api/salesDocuments'
import { customersApi } from '@/api/customers'
import { productsApi } from '@/api/products'
import { useOrganizationContextStore } from '@/stores/organizationContext'
import { useApiError } from '@/composables/useApiError'
import { usePermission } from '@/composables/usePermission'
import AppMoneyField from '@/components/AppMoneyField.vue'
import AppMobileRecordCard from '@/components/AppMobileRecordCard.vue'
import type { Customer, Product } from '@/types/models'
import type { SalesOrder, SalesOrderAudit, SalesOrderPayload } from '@/types/salesOrders'
import type { SalesDocument } from '@/types/salesDocuments'
const {t}=useI18n(); const {mdAndUp}=useDisplay(); const org=useOrganizationContextStore(); const {can}=usePermission(); const error=useApiError()
const rows=ref<SalesOrder[]>([]), quotes=ref<SalesDocument[]>([]), customers=ref<Customer[]>([]), products=ref<Product[]>([]), audits=ref<SalesOrderAudit[]>([]), loading=ref(false), saving=ref(false), editor=ref(false), selected=ref<SalesOrder|null>(null), notice=ref('')
const form=reactive({id:null as number|null,version:undefined as number|undefined,companyId:null as number|null,branchId:null as number|null,customerId:null as number|null,currency:'IRR',notes:'',lines:[{productId:null as number|null,quantity:1,unitPrice:0,discount:0}]})
const total=computed(()=>form.lines.reduce((s,l)=>s+l.unitPrice*l.quantity-l.discount,0)); const label=(x:string)=>t(`enum.${x}`,x); const money=(x:number)=>new Intl.NumberFormat(undefined,{maximumFractionDigits:0}).format(x)
async function load(){if(!org.companyId||!org.branchId)return;loading.value=true;try{[rows.value,quotes.value]=await Promise.all([salesOrdersApi.list(org.companyId,org.branchId),salesDocumentsApi.list(org.companyId,org.branchId)]);quotes.value=quotes.value.filter(q=>q.status==='ISSUED')}catch(e){error.set(e)}finally{loading.value=false}}
async function lookups(){const[c,p]=await Promise.all([customersApi.list({size:100}),productsApi.list({size:100})]);customers.value=c.content;products.value=p.content}
function open(row?:SalesOrder){Object.assign(form,{id:row?.id??null,version:row?.version,companyId:row?.companyId??org.companyId,branchId:row?.branchId??org.branchId,customerId:row?.customerId??null,notes:row?.notes??'',lines:row?.lines.map(l=>({productId:l.productId,quantity:l.quantity,unitPrice:l.unitPrice,discount:l.discount}))??[{productId:null,quantity:1,unitPrice:0,discount:0}]});editor.value=true;void lookups()}
function chooseProduct(line:{productId:number|null;unitPrice:number}){const p=products.value.find(x=>x.id===line.productId);if(p&&line.unitPrice===0)line.unitPrice=p.price}
async function save(){if(saving.value)return;if(!form.companyId||!form.branchId||!form.customerId||form.lines.some(l=>!l.productId||l.quantity<=0||l.discount>l.quantity*l.unitPrice)){error.set({code:'VALIDATION',message:'Invalid sales order'});return}saving.value=true;try{const p:SalesOrderPayload={companyId:form.companyId,branchId:form.branchId,customerId:form.customerId,currency:form.currency,notes:form.notes||undefined,lines:form.lines.map(l=>({productId:l.productId!,quantity:l.quantity,unitPrice:l.unitPrice,discount:l.discount||undefined})),expectedVersion:form.version};selected.value=form.id?await salesOrdersApi.update(form.id,p):await salesOrdersApi.create(p);editor.value=false;notice.value=t('salesDocuments.saved');await load()}catch(e){error.set(e)}finally{saving.value=false}}
async function show(row:SalesOrder){try{const [order,audit]=await Promise.all([salesOrdersApi.get(row.id),salesOrdersApi.audit(row.id)]);selected.value=order;audits.value=audit}catch(e){error.set(e)}}
async function convert(q:SalesDocument){if(saving.value)return;saving.value=true;try{selected.value=await salesOrdersApi.convert(q.id);notice.value=t('salesDocuments.saved');await load();if(selected.value)await show(selected.value)}catch(e){error.set(e)}finally{saving.value=false}}
async function action(kind:'confirm'|'cancel'){if(!selected.value||saving.value)return;saving.value=true;try{selected.value=await salesOrdersApi[kind](selected.value.id);await load()}catch(e){error.set(e)}finally{saving.value=false}}
onMounted(async()=>{if(!org.context)await org.refresh();await load()})
</script>
<template><section><v-alert v-if="!org.companyId||!org.branchId" type="warning" variant="tonal">{{t('salesDocuments.scopeRequired')}}</v-alert><v-alert v-if="notice" type="success" variant="tonal" class="mb-3">{{notice}}</v-alert><v-alert v-if="error.message.value" type="error" variant="tonal" class="mb-3">{{error.message.value}}</v-alert><v-card rounded="xl"><v-card-title class="d-flex align-center"><span>{{t('salesOrders.title')}}</span><v-spacer/><v-btn v-if="can('sales:create')" :disabled="!org.companyId||!org.branchId" prepend-icon="mdi-plus" color="primary" @click="open">{{t('salesOrders.new')}}</v-btn></v-card-title><v-card-text><v-data-table v-if="mdAndUp" :headers="[{title:'',key:'number'},{title:t('salesDocuments.status'),key:'status'},{title:t('salesDocuments.total'),key:'finalAmount'},{title:'',key:'actions'}]" :items="rows" :loading="loading"><template #item.status="{item}"><v-chip>{{label(item.status)}}</v-chip></template><template #item.finalAmount="{item}">{{money(item.finalAmount)}}</template><template #item.actions="{item}"><v-btn icon="mdi-eye-outline" variant="text" @click="show(item)"/></template></v-data-table><div v-else class="d-grid ga-3"><AppMobileRecordCard v-for="row in rows" :key="row.id" :label="row.number" @open="show(row)"><div>{{label(row.status)}} · {{money(row.finalAmount)}}</div></AppMobileRecordCard></div><v-divider class="my-4"/><div class="text-subtitle-1 mb-2">{{t('salesOrders.fromQuotation')}}</div><v-list density="compact"><v-list-item v-for="q in quotes" :key="q.id" :title="q.number" :subtitle="money(q.finalAmount)"><template #append><v-btn size="small" :loading="saving" @click="convert(q)">{{t('salesOrders.fromQuotation')}}</v-btn></template></v-list-item></v-list></v-card-text></v-card><v-dialog v-model="editor" :fullscreen="!mdAndUp" max-width="960"><v-card><v-toolbar color="transparent"><v-toolbar-title>{{form.id?t('common.edit'):t('salesOrders.new')}}</v-toolbar-title></v-toolbar><v-card-text><v-autocomplete v-model="form.customerId" :items="customers" item-title="displayName" item-value="id" :label="t('sales.customer')"/><v-card v-for="(line,i) in form.lines" :key="i" variant="outlined" class="pa-3 mb-3"><v-row><v-col cols="12" md="5"><v-autocomplete v-model="line.productId" :items="products" item-title="name" item-value="id" :label="t('sales.product')" @update:model-value="chooseProduct(line)"/></v-col><v-col cols="4" md="2"><v-text-field v-model.number="line.quantity" type="number" min="0.001" :label="t('sales.quantity')"/></v-col><v-col cols="4" md="2"><AppMoneyField v-model="line.unitPrice" :label="t('sales.unitPrice')"/></v-col><v-col cols="4" md="2"><AppMoneyField v-model="line.discount" :label="t('sales.discount')"/></v-col><v-col cols="12" md="1"><v-btn icon="mdi-delete-outline" variant="text" :disabled="form.lines.length===1" @click="form.lines.splice(i,1)"/></v-col></v-row></v-card><v-btn variant="tonal" @click="form.lines.push({productId:null,quantity:1,unitPrice:0,discount:0})">{{t('sales.addItem')}}</v-btn><div class="text-end text-h6 mt-4">{{t('salesDocuments.total')}}: {{money(total)}}</div></v-card-text><v-card-actions><v-btn @click="editor=false">{{t('common.cancel')}}</v-btn><v-spacer/><v-btn color="primary" :disabled="!form.customerId||form.lines.some(l=>!l.productId||l.quantity<=0||l.discount>l.quantity*l.unitPrice)" :loading="saving" @click="save">{{t('common.save')}}</v-btn></v-card-actions></v-card></v-dialog><v-dialog :model-value="!!selected" @update:model-value="v=>{if(!v)selected=null}" max-width="680"><v-card v-if="selected"><v-card-title>{{selected.number}} · {{label(selected.status)}}</v-card-title><v-card-text><div v-for="line in selected.lines" :key="line.id" class="d-flex justify-space-between py-2"><span>{{line.name}} × {{line.quantity}}</span><span>{{t('salesOrders.reserved')}}: {{line.reservedQuantity}} · {{t('salesOrders.backordered')}}: {{line.backorderedQuantity}} · {{t('salesOrders.fulfilled')}}: {{line.fulfilledQuantity}}</span></div><v-divider class="my-4"/><div class="text-subtitle-2">{{t('salesDocuments.history')}}</div><v-list density="compact"><v-list-item v-for="audit in audits" :key="audit.id" :title="label(audit.action)" :subtitle="audit.occurredAt"/></v-list></v-card-text><v-card-actions><v-btn v-if="selected.status!=='CANCELLED'&&can('sales:edit')" @click="open(selected);selected=null">{{t('common.edit')}}</v-btn><v-btn v-if="selected.status==='DRAFT'&&can('sales:confirm')" color="primary" :loading="saving" @click="action('confirm')">{{t('salesOrders.confirm')}}</v-btn><v-btn v-if="selected.status!=='CANCELLED'&&can('sales:edit')" color="error" @click="action('cancel')">{{t('salesDocuments.cancel')}}</v-btn></v-card-actions></v-card></v-dialog></section></template>
